    faqs: [
      {q: "구동사와 숙어 차이는?", a: "구동사 (phrasal verb)는 \"동사 + 전치사\" 결합으로 의미 변화. 예: get up (일어나다), look up (찾아보다). 숙어 (idiom)는 \"의미 단위\" 표현. 예: break a leg (행운을), piece of cake (쉬움). 구동사는 패턴 학습 (전치사 의미), 숙어는 통째 외우기. 둘 다 변별 영역이라 함께 학습이 답이에요. 자세한 숙어 가이드는 \"숙어·관용 표현\" 페이지 참고."},
      {q: "빈출 구동사 어디서 찾나요?", a: "수능 5개년 + 내신 기출 분석으로 빈출 150개 선별 가능해요. 1:1 과외에서 학생 학교 기출 + 평가원 구동사 정리 효율적이에요. 자료: \"능률 VOCA 수능\"·\"천일문 완성\"에 빈출 구동사 포함. 추천 책: \"Phrasal Verb Organiser\" (Cambridge)."},
      {q: "전치사 의미가 너무 많아 헷갈려요", a: "핵심 6개 (in·out·up·down·off·on) 의미만 정확히 이해하면 90% 추론 가능해요. up = 위로·완성, down = 아래로·실패, in = 안으로·참여, out = 밖으로·완료, off = 떨어짐·시작, on = 위로·계속. 매주 1개 전치사씩 정리 추천. 1:1 과외에서 전치사별 정리 효율적이에요."},
      {q: "분리 가능·불가 어떻게 구분?", a: "기본 규칙: 자동사 + 전치사 (분리 불가·look at·get over). 타동사 + 부사 (분리 가능·look up·turn off). 다만 예외 있어 매주 분리 패턴 5개씩 정리 + 영작 활용이 답이에요. 1:1 과외에서 패턴 학습 추천."},
    ],
