    faqs: [
      {q: "수동태 변환이 너무 어려워요", a: "변환 3단계가 답이에요. (1) 능동의 목적어 → 수동의 주어. (2) 동사 → be + p.p. (be 시제는 능동의 시제). (3) 능동의 주어 → by + 목적격. 매주 변환 10문항 + 1:1 첨삭이 1·2등급의 비밀입니다. 6주 정착이면 자동화돼요."},
      {q: "by 외 전치사 어떻게 외우나요?", a: "빈출 표현 30개 정리가 답이에요. (1) 감정: be interested in·be surprised at·be pleased with·be tired of. (2) 재료·구성: be made of (재료 보임)·be made from (재료 보이지 않음)·be filled with·be covered with. (3) 결과: be known for (특징)·be known to (사람들에게)·be known as (~로서)·be known by (~에 의해). 매주 5개씩 외우기 + 영작 활용이 답이에요."},
      {q: "4형식 수동태 두 가지가 헷갈려요", a: "표준: 4형식 \"S + V + IO + DO\" 두 가지 수동태 가능. (1) IO를 주어로: \"I was given a book.\" (전치사 X). (2) DO를 주어로: \"A book was given to me.\" (전치사 to 필수). 빈출 함정: 전치사 누락. 동사별 전치사 외우기 (give·send·tell·show → to·buy·get·make → for·ask → of). 1:1 과외에서 첨삭 추천."},
      {q: "관용 수동 표현 어떻게?", a: "관용 표현은 수동태 형태이지만 능동 의미예요. (1) be born (\"태어나다\")·be married (\"결혼하다\")·be tired (\"피곤하다\")·be excited (\"흥분하다\"). (2) 변환 X·외우기. 매주 관용 표현 10개 정리 + 영작 활용이 답이에요."},
    ],
