    phases: [["1단계","관계대명사 5개","who·whom·whose·which·that"],["2단계","관계부사 4개","where·when·why·how"],["3단계","제한·계속적 용법","콤마 유무"],["4단계","함정 정복","what·that 차이·생략"]],
    areas: [
      {name: "관계대명사 5개 (who·whom·whose·which·that)", body: "관계대명사는 5개로 분류돼요. (1) who: 사람 주격 (\"the boy who runs\"). (2) whom: 사람 목적격 (\"the boy whom I met\"·구어에서 who로 대체 가능). (3) whose: 사람·사물 소유격 (\"the boy whose name is John\"·\"the book whose cover is red\"). (4) which: 사물·동물 주격·목적격 (\"the book which is on the desk\"). (5) that: 사람·사물 모두 가능·제한적 용법만 (\"the boy that is tall\"·\"the book that I read\"). 선행사 (관계사 앞 명사) + 격 (주격·목적격·소유격)에 따라 결정. 매주 관계대명사 변환 10문항 + 1:1 첨삭 추천."},
      {name: "관계부사 4개 (where·when·why·how)", body: "관계부사는 4개로 분류돼요. (1) where: 장소 (\"the place where I live\" = \"the place in which I live\"). (2) when: 시간 (\"the day when I met him\" = \"the day on which I met him\"). (3) why: 이유 (the reason why ~). (4) how: 방법 (the way how ~ 또는 the way ~ 둘 중 하나만 사용). 관계부사 = 전치사 + 관계대명사. 매주 관계부사 5문항 + 1:1 첨삭 추천. 1·2등급의 변별 영역이에요."},
      {name: "제한·계속적 용법 (콤마 유무)", body: "관계사는 제한적 용법과 계속적 용법으로 나뉘어요. (1) 제한적 용법: 콤마 X·선행사를 한정 (\"He has a son who lives in Seoul.\" = 서울에 사는 아들 1명만). (2) 계속적 용법: 콤마 + 관계사·선행사 추가 설명 (\"He has a son, who lives in Seoul.\" = 그에게 아들이 있는데, 그가 서울에 산다). that은 계속적 용법 X (which·who 사용). 콤마 유무로 의미가 달라지는 빈출 함정. 매주 5문항 + 1:1 첨삭이 답이에요."},
      {name: "함정 패턴 (what·that 차이·생략)", body: "관계사 함정 패턴 5가지: (1) what vs that: what = 선행사 포함 (\"the thing(s) which/that\")·that = 선행사 별도. (2) 관계대명사 생략: 목적격 관계대명사 생략 가능 (\"the book (that) I read\"). (3) 전치사 + 관계대명사: 전치사를 관계사 앞으로 (\"the house in which I live\"). (4) that 사용 우선: 최상급·서수·all·every 뒤. (5) 관계부사 vs 관계대명사: 선행사가 장소이지만 동사가 직접 목적어 받으면 관계대명사 사용 (\"the place which I visited\"). 함정 패턴 정리 + 5개년 기출 분석이 답이에요."},
    ],
