    checklist: ["관계대명사 5개 (who·whom·whose·which·that) 정확히 사용?","관계부사 4개 (where·when·why·how) 정복?","제한·계속적 용법 (콤마 유무) 구분?","what vs that 차이 정복?","관계대명사 생략 + 전치사 + 관계대명사 정착?"],
    checklistTitle: "관계사 체크리스트",
    checklistSub: "월 1회 점검",
    faqs: [
      {q: "관계대명사 어떻게 선택?", a: "2단계 결정이 답이에요. (1) 선행사 종류: 사람 (who·whom·whose)·사물 (which·whose)·둘 다 (that). (2) 격: 주격 (who·which·that)·목적격 (whom·which·that)·소유격 (whose). 예: \"the boy who runs\" (사람·주격)·\"the book which I read\" (사물·목적격). 매주 변환 10문항 + 1:1 첨삭이 답이에요."},
      {q: "관계부사와 관계대명사 차이는?", a: "관계부사 = 전치사 + 관계대명사예요. (1) where = in/at/on which (장소). (2) when = in/at/on which (시간). (3) why = for which (이유). (4) how = in which (방법). 예: \"the place where I live\" = \"the place in which I live\". 동사가 목적어를 직접 받으면 관계대명사 사용 (\"the place which I visited\"). 1:1 과외에서 첨삭 추천."},
      {q: "제한적 vs 계속적 용법 어떻게?", a: "콤마 유무로 결정해요. (1) 제한적 (콤마 X): 선행사 한정 (\"He has a son who lives in Seoul.\" = 서울에 사는 아들만). (2) 계속적 (콤마 +): 선행사 추가 설명 (\"He has a son, who lives in Seoul.\" = 아들이 있는데 서울에 산다). that은 계속적 용법 X. 빈출 함정. 매주 5문항 + 1:1 첨삭이 답이에요."},
      {q: "what vs that 헷갈려요", a: "what = 선행사 포함 (\"the thing(s) which/that\")·that = 선행사 별도. 예: \"What I want is happiness.\" (= \"The thing that I want is happiness.\")·\"The book that I read is interesting.\" (선행사 the book). what이 사용되면 앞에 선행사 X. 매주 5문항 + 1:1 첨삭이 답이에요."},
    ],
