      body: "자주 틀리는 영문법은 영어 1·2등급의 결정적 분기점이에요. 빈출 함정 50개 정복이면 시험 직전 점수 ⬆️ 가능합니다. 핵심은 \"동사 형태 함정 + 어순 함정 + 가산·불가산 + 헷갈리는 표현\" 4박자예요. 학년별 단계: 초5·6 (단수·복수·be 동사 vs 일반동사 등 기초)·중1·2·3 (시제 일치·관사·전치사 등 본격)·고1·2·3 (수능 변별 5개년 기출). 매일 30분 + 매주 빈출 함정 5~10개 정리가 표준이에요. 1:1 과외에서 약점 함정 진단 + 맞춤 학습 추천."
