    phases: [["1단계","동사 형태 함정","시제·수일치·인칭"],["2단계","어순 함정","간접의문문·강조·도치"],["3단계","가산·불가산 + 관사","a/an·the·관사 X"],["4단계","헷갈리는 표현","lay vs lie 등"]],
    areas: [
      {name: "동사 형태 함정 (시제·수일치·인칭)", body: "동사 형태 함정 5가지: (1) 시제 일치: 주절 과거 → 종속절 과거 또는 과거완료. (2) 수일치: 주어가 단수 vs 복수 (\"Each of the students is\" / \"All of the students are\"). (3) 3인칭 단수 현재: -s 추가 (\"He plays\"). (4) 동사 vs 동명사 (-ing): enjoy·avoid·finish + -ing / want·hope·decide + to + 동사원형. (5) p.p. (과거분사) vs -ing: 능동·진행 (-ing) / 수동·완료 (p.p.). 매주 동사 형태 함정 5문항 + 1:1 첨삭이 답이에요."},
      {name: "어순 함정 (간접의문문·강조·도치)", body: "어순 함정 5가지: (1) 간접의문문: 의문사 + 주어 + 동사 (\"I know what he wants.\" / X \"I know what does he want.\"). (2) 부정어 도치: 부정어 + 조동사 + 주어 + 동사 (\"Never have I seen such beauty.\"). (3) 강조 it ~ that: \"It was John who broke the window.\". (4) 형용사 어순: opinion + size + age + shape + color + origin + material (\"a beautiful small old round red Korean wooden table\"). (5) 부사 어순: 빈도 부사 (always·usually·often·sometimes·never)는 일반동사 앞·be 동사 뒤. 매주 어순 함정 5문항 + 1:1 첨삭이 답이에요."},
      {name: "가산·불가산 명사 + 관사", body: "가산·불가산 + 관사 함정 5가지: (1) 가산 명사: a/an + 단수·-s 복수 (\"a book\"·\"books\"). (2) 불가산 명사: 관사 X·복수 X (\"water\"·\"information\"·\"advice\"). (3) 빈출 불가산: information·advice·news·furniture·equipment·luggage·baggage·money·water·food·music. (4) 가산 + 불가산 둘 다: chicken (닭 / 닭고기)·glass (유리잔 / 유리)·hair (머리카락 한 가닥 / 머리카락 전체). (5) 관사: a/an (불특정·단수·자음·모음 구분)·the (특정·반복 언급·유일·최상급·서수). 매주 명사·관사 함정 5문항 + 1:1 첨삭이 답이에요."},
      {name: "헷갈리는 표현 (lay vs lie 등)", body: "헷갈리는 표현 빈출 10개: (1) lay (놓다·타동사) vs lie (눕다·자동사 / 거짓말하다). (2) rise (오르다·자동사) vs raise (올리다·타동사). (3) affect (영향을 미치다·동사) vs effect (효과·명사). (4) advise (조언하다·동사) vs advice (조언·명사). (5) accept (받아들이다) vs except (제외하고). (6) borrow (빌리다) vs lend (빌려주다). (7) bring (가져오다) vs take (가져가다). (8) say vs tell vs speak vs talk. (9) see vs watch vs look. (10) listen vs hear. 매주 5개씩 정리 + 영작 활용이 답이에요. 1·2등급의 변별 영역이에요."},
    ],
