    checklistTitle: "영어 주제 파악 체크리스트",
    checklistSub: "월 1회 점검",
    faqs: [
      {q: "Main Idea와 Topic 차이는?", a: "표준 2가지가 답이에요. (1) Main Idea (요지·중심 내용): 글이 \"무엇을 말하는가\" (What is being said). 더 길고 구체적. \"환경 보호의 중요성과 실천 방법\". (2) Topic (주제·소재): 글이 \"무엇에 관한 것인가\" (What it is about). 더 짧고 일반적. \"환경 보호\". 빈출 함정·매주 4유형 정리 + 1:1 첨삭이 답이에요."},
      {q: "Topic Sentence 어디 있나요?", a: "Topic Sentence는 보통 단락 첫 문장이에요. 표준 4가지 위치: (1) 단락 첫 문장 (가장 빈출). (2) 단락 두 번째 문장 (도입 후). (3) 단락 마지막 문장 (Concluding Sentence와 결합). (4) 글 첫 문장 (전체 주제 제시). 매 글 시작 시 Topic Sentence 표시 + 1:1 첨삭이 1·2등급의 비밀이에요."},
      {q: "주제 파악이 너무 어려워요", a: "5단계가 답이에요. (1) 제목·소제목 확인. (2) 첫 문장 정독 (Topic Sentence). (3) 결론 정독 (Concluding Sentence). (4) 반복 단어 표시. (5) 1문장 요약. 매 글 5단계 + 매주 5지문 + 1:1 첨삭이 1·2등급의 비밀입니다. 6주 정착이면 자연스러워져요."},
      {q: "초5 영어 주제 파악 어디부터?", a: "초5·6은 제목·첫 문장 활용이 우선이에요. 짧은 영어 글 (100~200단어) + 제목 확인 + 1문장 요약. 매일 20~30분 + 매주 5개. 본격적인 5단계는 중1부터. 어휘 부족 시 어휘 보강 우선. 1:1 과외에서 흥미 형성 + 단서 학습 추천."},
    ],
