      body: "영어 세부 내용 파악은 시험 정확성의 결정적 도구예요. 시험 점수·실생활 활용·1·2등급 변별의 핵심 영역입니다. 핵심은 \"정확성·꼼꼼함 + 5W1H + 빈출 유형 + 함정 정복\" 4박자예요. 단순 글 읽기 X. \"5W1H + 키워드 + 숫자·이름·날짜\" 정확 추출이 답이에요. 영어 빈출 유형: True/False·Specific Detail·Reference (대명사 가리키는 것). 학년별 단계: 초3·4 (5W1H 입문) → 초5·6 (정확한 추출 정착) → 중1~3 (시험 빈출 유형) → 고1~3 (변별 영역). 매일 20~30분 + 매주 5지문 분석이 표준이에요. 1:1 과외에서 약점 진단 + 맞춤 학습 추천."
