    mistakes: [
      {title: "단어 모르고 넘기기", body: "가장 큰 함정이에요. 모르는 단어 그냥 넘기면 핵심 정보 X. 매 글마다 모르는 단어 표시 + 사전 또는 맥락 추론이 답입니다. 매주 어휘 정리가 1·2등급의 비밀이에요."},
      {title: "시제·시간 함정", body: "영어는 시제·시간 표현이 한국어와 달라요. \"in 1990\" (1990년에·시점) vs \"by 1990\" (1990년까지·완료). \"since\" (~이래로) vs \"for\" (~동안). 매 풀이 시 시제·시간 표시 + 검산이 1·2등급의 비밀이에요."},
      {title: "Reference (대명사 지시) 오해", body: "대명사 (it·they·this·that)가 가리키는 대상 잘못 파악 빈출 함정. 매 대명사 등장 시 \"이 대명사가 가리키는 대상은 무엇인가\" 표시 + 검산이 답이에요. 영어 특화 함정이에요."},
    ],
