      body: "영어 빈칸 추론은 수능 영어의 결정적 변별 영역이에요. 1·2등급과 3등급을 가르는 핵심 영역입니다. 핵심은 \"빈칸 추론의 본질 + 5단계 풀이 + 빈출 5유형 + 함정 정복\" 4박자예요. 단순 단어 매칭 X. \"전체 흐름 + 빈칸 앞뒤 + 논리 흐름 + 선택지 매칭 + 검산\" 5단계가 답이에요. 영어는 한국어와 달리 \"connector words\" (However·Therefore·Moreover 등)가 결정적 단서예요. 학년별 단계: 중3 (입문) → 고1·2 (정착) → 고3 (수능 변별). 매일 30~45분 + 매주 5지문 빈칸 풀이 + 1:1 첨삭이 표준이에요. 1:1 과외에서 약점 진단 + 맞춤 학습 추천."
