    phases: [["1단계","빈칸 추론 본질","논리·맥락·어휘"],["2단계","풀이 5단계","전체→앞뒤→connector→매칭→검산"],["3단계","빈출 5유형","개념·근거·결론·전환·예시"],["4단계","함정 정복","단어만 매칭·맥락 X"]],
    areas: [
      {name: "영어 빈칸 추론의 본질 (논리·맥락·어휘)", body: "영어 빈칸 추론의 본질은 \"논리 + 맥락 + 어휘\"의 종합이에요. (1) 논리: 빈칸 앞뒤 문장의 논리 관계 (인과·대조·예시·전환). (2) 맥락: 글 전체 흐름과 주제 (부분 X·전체). (3) 어휘: 빈칸을 채울 적정 어휘 (개념·전문용어). (4) Connector Words 단서: However·Therefore·Moreover·In contrast 등이 빈칸 앞뒤 논리를 결정. 단순 단어 매칭 X·논리 + 맥락 + 어휘 종합이 답이에요. 빈출 함정: 단어만 매칭·맥락 무시. 매 빈칸 풀이 시 본질 점검 + 1:1 첨삭이 답이에요. 1·2등급의 결정적 도구예요."},
      {name: "빈칸 풀이 5단계 (전체→앞뒤→connector→매칭→검산)", body: "영어 빈칸 풀이 표준 5단계: (1) 전체 읽기: 글 전체 흐름·주제 파악. (2) 빈칸 앞뒤 정독: 빈칸 직전·직후 문장 정밀 분석. (3) Connector Words 분석: However (대조)·Therefore (결과)·Moreover (추가)·For example (예시)·In contrast (대조). (4) 선택지 매칭: 각 선택지를 빈칸에 넣어 논리 검증. (5) 검산: 글 전체 흐름과 일치하는지 확인. 단순 \"단어 매칭\" X. 5단계가 답이에요. 빈출 함정: 5단계 일부 누락. 매 빈칸 풀이 5단계 + 1:1 첨삭이 1·2등급의 결정적 도구예요. 매주 5지문 + 시간 측정이 답이에요."},
      {name: "빈출 5유형 (개념·근거·결론·전환·예시)", body: "영어 빈칸 추론 빈출 5유형: (1) 개념 빈칸: 글의 핵심 개념·정의. \"This phenomenon is called [____]\". (2) 근거 빈칸: 주장 뒷받침 근거. \"because [____]\"·\"since [____]\". (3) 결론 빈칸: 글의 결론·시사점. \"Therefore, [____]\"·\"In conclusion, [____]\". (4) 전환 빈칸: 흐름 전환 표현. \"However, [____]\"·\"On the other hand, [____]\". (5) 예시 빈칸: 구체적 예시. \"For example, [____]\"·\"For instance, [____]\". 매 유형별 풀이 패턴: 5단계 + 유형 인식 + 매칭. 매주 빈출 유형 5문항 + 1:1 첨삭이 답이에요. 5개년 기출 정밀 분석이 1·2등급의 비밀이에요."},
      {name: "함정 패턴 (단어만 매칭·맥락 무시·자기 견해)", body: "영어 빈칸 추론 함정 5가지: (1) 단어만 매칭 (논리 X·단어 비슷하면 정답이라 추측). (2) 맥락 무시 (빈칸 주변만 보고 전체 X). (3) 자기 견해 추가 (텍스트 단서 X). (4) 검산 누락 (5단계 일부만). (5) 시간 부족 (1지문 1.5분 이내·시간 분배 X). 함정 패턴 정리 + 5개년 기출 분석이 답이에요. 1·2등급의 결정적 분기점이에요. 1:1 과외에서 함정 학습 추천. Connector Words 30개 정리가 1·2등급의 결정적 비밀이에요."},
    ],
    tiers: [
      {label: "중3 (빈칸 입문)", body: "빈칸 추론 본질 + 5단계 입문 + 빈출 5유형 입문 + Connector Words 10개. 매일 30분 + 매주 5지문 빈칸 풀이. 1:1 과외에서 5단계 학습 추천. 모의고사 빈칸 풀이 시작."},
      {label: "고1·2 (정착)", body: "5단계 모두 + 빈출 5유형 정착 + Connector Words 30개 + 함정 패턴. 매일 30~45분 + 매주 10지문 + 시간 측정. 1:1 과외에서 함정 패턴 학습 추천."},
      {label: "고3 (수능 변별)", body: "5개년 수능·EBS 정밀 분석 + 변별 영역 + 시간 단축 (1지문 1.5분). 매일 45분~1시간 + 매주 15지문 + 1:1 첨삭. 1:1 과외에서 만점 도전 코칭 추천."},
    ],
    mistakes: [
      {title: "단어만 매칭", body: "가장 큰 함정이에요. 빈칸 추론은 \"논리·맥락·어휘 종합\"·단순 단어 X. 매 풀이 시 \"논리 흐름이 맞는가\" 검산이 답입니다. 1·2등급의 결정적 분기점이에요."},
      {title: "Connector Words 무시", body: "However·Therefore·Moreover 등이 빈칸 앞뒤 논리를 결정. Connector Words 30개 정리 + 매주 학습이 답입니다. 1·2등급의 결정적 비밀이에요."},
      {title: "맥락 무시 (부분만 보기)", body: "빈칸 주변만 보고 전체 X. 5단계 (전체·앞뒤·connector·매칭·검산) 모두 거쳐야 답. 매 풀이 시 1단계 (전체 읽기) 누락 X. 1:1 과외에서 첨삭 추천."},
    ],
    checklist: ["빈칸 추론 본질 (논리·맥락·어휘) 이해?","풀이 5단계 (전체·앞뒤·connector·매칭·검산) 정착?","빈출 5유형 (개념·근거·결론·전환·예시) 정복?","Connector Words 30개 외우기?","매주 빈칸 5지문 + 시간 측정?"],
    checklistTitle: "영어 빈칸 추론 체크리스트",
    checklistSub: "월 1회 점검",
    faqs: [
      {q: "영어 빈칸 추론이 너무 어려워요", a: "5단계가 답이에요. (1) 전체 읽기 (글 흐름·주제). (2) 빈칸 앞뒤 정독. (3) Connector Words 분석 (However·Therefore·Moreover 등). (4) 선택지 매칭. (5) 검산. 매 빈칸 5단계 + 매주 5지문 + 1:1 첨삭이 1·2등급의 비밀입니다. 6주 정착이면 자연스러워져요."},
      {q: "Connector Words 어떻게 외우?", a: "표준 30개 카테고리별 정리가 답이에요. (1) 대조 (10개): However·On the other hand·In contrast·Whereas·Although·Despite·Nevertheless·Yet·Still·But. (2) 결과 (5개): Therefore·Thus·Hence·Consequently·As a result. (3) 추가 (5개): Moreover·Furthermore·In addition·Additionally·Besides. (4) 예시 (5개): For example·For instance·Such as·Including·Specifically. (5) 시간 (5개): Meanwhile·Subsequently·Previously·Eventually·Finally. 매주 10개씩 + 영작 활용 + 1:1 첨삭이 답이에요. 30개 정착이 1·2등급의 비밀이에요."},
      {q: "빈칸 추론 시간 단축 어떻게?", a: "표준 4단계가 답이에요. (1) 1지문 1.5분 목표. (2) 5단계 정착 (시간 X·자동화). (3) 빈출 5유형 인식 + 빠른 매칭. (4) 매주 시간 측정 + 정확도 90%+. 정확도 X·시간 단축 무용지물. 정확도 + 시간 균형이 1·2등급의 비밀이에요. 1:1 과외에서 시간 관리 코칭 추천."},
      {q: "빈칸 추론 어디부터?", a: "중3부터 본격 시작이 정석이에요. 모의고사·수능에서 본격 등장. (1) 중3: 5단계 입문 + 빈출 유형 + Connector Words 10개. (2) 고1·2: 정착 + 함정 패턴 + Connector Words 30개. (3) 고3: 수능 변별 + 시간 단축. 초·중1·2는 다른 독해력 (skill·theme) 우선. 1:1 과외에서 학년별 진단 추천."},
    ],
