    faqs: [
      {q: "영어 문맥 추론이 너무 어려워요", a: "5단계가 답이에요. (1) 단서 찾기 (모르는 단어 주변). (2) 연결 (단서들 관계). (3) 가설 (단서 종합 + 의미). (4) 매칭 (선택지). (5) 검증 (글에 넣어 자연스러운가). 매 추론 5단계 + 매주 5지문 + 1:1 첨삭이 1·2등급의 비밀입니다. 6주 정착이면 자연스러워져요."},
      {q: "5단서 어떻게 찾나요?", a: "표준 5가지가 답이에요. (1) 동의어: \"or\"·\"that is\"·\"in other words\" 뒤. (2) 반의어: \"but\"·\"however\"·\"unlike\" 뒤. (3) 예시: \"such as\"·\"for example\" 뒤. (4) 정의: \"is\"·\"means\"·\"refers to\". (5) 인과: \"because\"·\"therefore\". 매 모르는 단어마다 5단서 점검 + 1:1 첨삭이 1·2등급의 비밀이에요."},
      {q: "사전 학습 vs 문맥 추론?", a: "둘 다 필요해요. (1) 사전 학습 (평소): 학년별 적정 어휘량 (중1 2천·고3 5천+) 정착. (2) 문맥 추론 (시험): 모르는 단어 발견 시 5단서 활용. 사전 학습만으로는 모든 단어 X·문맥 추론만으로는 시간 부족. 균형이 답이에요. 1:1 과외에서 균형 학습 추천."},
      {q: "초·중1 영어 문맥 추론?", a: "문맥 추론은 어휘 정착 후 (중1부터)가 정석이에요. 초등은 어휘·문법 기초 + 짧은 글 이해 우선. 추론 강요 X. 중1부터 5단서 입문 + 모르는 단어 표시. 1:1 과외에서 학년별 진단 추천."},
    ],
