      body: "영어 속독은 수능 70분 / 45문항 해결의 결정적 도구예요. 1문항당 약 1.5분 배정·속독 없이는 시간 부족·1·2등급 어렵습니다. 핵심은 \"속독의 정의 + 5가지 기술 + 학년별 적정 속도 + 함정 정복\" 4박자예요. 단순 빠르게 읽기 X. \"정확도 유지하면서 + 적정 속도로\"가 답이에요. 직독직해 → 속독 순서 학습이 1·2등급의 비밀입니다. 매일 30분 + 매주 5지문 시간 측정 + 1:1 첨삭이 표준이에요. 1:1 과외에서 약점 진단 + 맞춤 학습 추천."
