    tiers: [{label:"초3·4·5·6 (기초)", body:"단어 받아쓰기·짧은 문장 완성·그림 보고 영어로 쓰기. 철자·대소문자 규칙 기초. 1:1 과외 30분."},{label:"중1·2·3 (체계 정리)", body:"문장 완성·해석·기본 영작. 주술 일치·시제 감점 패턴 교정. 조건 영작 5단계 학습. 1:1 첨삭 추천."},{label:"고1·2·3 (내신 완성)", body:"조건 영작·의견 서술·PEEL 구조. 내신 서술형 배점별 시간 배분 완성. 기출 5개년 서술형 유형 분석."}],
    mistakes: [{title:"조건을 끝까지 안 읽고 쓰기", body:"조건 영작에서 가장 많은 실수예요. 단어 수 조건·포함해야 할 단어·시제 조건을 먼저 형광펜으로 체크하는 습관이 핵심. 다 쓴 후에도 조건 하나씩 대조 확인이 필수예요."},{title:"관사 (a/an/the) 습관적 누락", body:"한국어에는 관사가 없어서 영어 서술형에서 자주 빠뜨려요. 명사 앞에 관사가 필요한지 체크하는 루틴 필요. 특히 처음 언급 = a/an·두 번째 언급 = the·세상에 하나뿐 = the 기준으로 정리해요."},{title:"시제 통일 안 됨", body:"문장 전반은 과거 시제인데 서술형 답안만 현재 시제로 쓰는 실수. 지문의 시제 → 답안 시제가 일치해야 해요. 작성 후 검토 단계에서 시제 통일 여부를 반드시 확인하는 습관이 필요해요."}],
    checklist: ["서술형 5가지 유형 구분 가능?","감점 패턴 TOP 7 인지?","조건 영작 5단계 순서 암기?","PEEL 구조 (고등) 적용 가능?","검토 3단계 루틴 실행?"],
    checklistTitle: "영어 서술형 정복 체크리스트", checklistSub: "초3~고3 학년별 점검",
    faqs: [{q:"영어 서술형은 부분 점수가 있나요?", a:"학교마다 채점 기준이 다르지만, 대부분 부분 점수제예요. 핵심 어휘가 맞거나 구조가 맞으면 부분 점수를 받을 수 있어요. 그래서 모르더라도 아는 것부터 쓰는 게 중요해요. 1:1 과외에서는 실제 학교 기출 채점 기준을 분석해 전략을 세워요."},{q:"조건 영작에서 단어 수는 어떻게 세나요?", a:"보통 단어 하나를 1개로 세요. won't는 1개·don't know는 2개. 관사 a·the도 각각 1개로 세요. 학교마다 기준이 다를 수 있으니 기출 문제에서 확인하는 게 가장 정확해요. 1:1 과외에서 학교별 기출 분석으로 대비해요."},{q:"영어 서술형 대비는 언제부터 시작해야 하나요?", a:"초3~4는 단어 철자·문장 구조 기초, 초5~6는 문장 완성과 간단한 영작, 중학교부터 본격적인 서술형 대비가 필요해요. 고등은 조건 영작·의견 서술이 핵심이라 중3 때부터 미리 준비하면 유리해요."}],
    related: [{label:"영어 수행평가 대비", href:"/study/english/perform/assessment/"},{label:"영어 내신 대비", href:"/study/english/exam/naesin/"},{label:"영문법 완벽 가이드", href:"/study/english/grammar/guide/"},{label:"영어 학년별 로드맵", href:"/study/english/"},{label:"기출문제 분석", href:"/study/english/exam/past/"}],
